def _split_segments(segment: str) -> list[str]:
    parts: list[str] = []
    buf: list[str] = []
    depth = 0
    in_s = in_d = esc = False
    i = 0
    while i < len(segment):
        ch = segment[i]
        if esc:
            buf.append(ch)
            esc = False
            i += 1
            continue
        if ch == "\\" and (in_s or in_d):
            buf.append(ch)
            esc = True
            i += 1
            continue
        if not in_d and ch == "'" and not in_s:
            in_s = True
            buf.append(ch)
            i += 1
            continue
        if in_s:
            buf.append(ch)
            if ch == "'":
                in_s = False
            i += 1
            continue
        if not in_s and ch == '"' and not in_d:
            in_d = True
            buf.append(ch)
            i += 1
            continue
        if in_d:
            buf.append(ch)
            if ch == '"':
                in_d = False
            i += 1
            continue
        if ch == "(":
            depth += 1
        elif ch == ")" and depth > 0:
            depth -= 1
        if depth > 0:
            buf.append(ch)
            i += 1
            continue
        two = segment[i : i + 2]
        if two in {"&&", "||"}:
            value = "".join(buf)
            if value:
                parts.append(value)
            buf = []
            i += 2
            continue
        if ch in {"|", ";"}:
            value = "".join(buf)
            if value:
                parts.append(value)
            buf = []
            i += 1
            continue
        buf.append(ch)
        i += 1
    value = "".join(buf)
    if value:
        parts.append(value)
    return parts


