def _read_tsv(path: Path) -> list[PlanCommandRow]:
    rows: list[PlanCommandRow] = []
    with path.open(encoding="utf-8", errors="replace") as handle:
        for idx, line in enumerate(handle):
            line = line.rstrip("\n")
            if idx == 0:
                continue
            parts = line.split("\t")
            parts += [""] * (7 - len(parts))
            try:
